```java
import java.util.List;
import java.util.stream.Collectors;

public class StockPriceManipulation {
    public static void main(String[] args) {
        // Example usage:
        List<Double> stockPrices = List.of(100.0, 105.0, 102.0, 108.0);
        double targetPrice = 105.0;
        int daysToMoveAverage = 3;
        double movingAverage = calculateMovingAverage(stockPrices, daysToMoveAverage);

        System.out.println("Initial Prices: " + stockPrices);
        System.out.println("Target Price: " + targetPrice);
        System.out.println("Days to Move Average: " + daysToMoveAverage);
        System.out.println("Moving Average: " + movingAverage);
        System.out.println("Final Prices: " + moveStockPrices(stockPrices, targetPrice, daysToMoveAverage));
    }

    private static double calculateMovingAverage(List<Double> prices, int windowSize) {
        long sum = 0L;
        for (int i = 0; i < windowSize; i++) {
            sum += prices.get(i);
        }
        return sum / windowSize;
    }

    private static List<Double> moveStockPrices(List<Double> prices, double targetPrice, int daysToMoveAverage) {
        List<Double> finalPrices = new ArrayList<>();
        for (double price : prices) {
            double average = calculateMovingAverage(prices.subList(0, daysToMoveAverage), daysToMoveAverage);
            if (price > average && price > targetPrice) {
                finalPrices.add(price * 1.1); // Increase by 10%
            } else if (price < average && price < targetPrice) {
                finalPrices.add(price * 0.9); // Decrease by 10%
            } else {
                finalPrices.add(price);
            }
        }
        return finalPrices;
    }
}
```

